class Solution {
    public long maximumTripletValue(int[] nums){
        int maximum=nums[0],difference=0;
        long answer=0;
        for(int k=1;k<nums.length;k++){
            answer=Math.max(answer,(long)difference*nums[k]);
            difference=Math.max(difference,maximum-nums[k]);
            maximum=Math.max(maximum,nums[k]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumTripletValue(nums:IntArray):Long{
        var maximum=nums[0];
        var difference=0;
        var answer=0L;
        for(k in 1 until nums.size){
            answer=maxOf(answer,difference.toLong()*nums[k]);
            difference=maxOf(difference,maximum-nums[k]);
            maximum=maxOf(maximum,nums[k])
        };
        return answer
    }
}

